//! C ABI for the TPT Kinetix container tools.
//!
//! Three things are exposed: [`tk_probe_json`] lists the tracks of a WebM, IVF or
//! MP4 file as JSON, [`tk_faststart`] writes a copy with the index moved to the
//! front, and the version and error-string helpers. The header is
//! `include/tpt_kinetix.h`, generated by cbindgen (`just ffi-header`).
//!
//! Conventions: every string returned is owned by the caller and released with
//! [`tk_free_string`]; a function that fails returns null (or -1) and the reason
//! is available from [`tk_last_error`] on the same thread. No Rust panic crosses
//! the boundary.

use std::cell::RefCell;
use std::ffi::{c_char, c_int, CStr, CString};
use std::fs::File;
use std::io::{BufWriter, Read, Write};
use std::panic::{catch_unwind, AssertUnwindSafe};
use std::path::Path;

use tpt_kinetix_core::codec::MediaType;
use tpt_kinetix_core::stream::StreamInfo;
use tpt_kinetix_demux::{IvfDemuxer, MkvReader, Mp4Reader};

thread_local! {
    static LAST_ERROR: RefCell<Option<CString>> = const { RefCell::new(None) };
}

fn set_error(message: impl Into<String>) {
    let text = message.into().replace('\0', " ");
    LAST_ERROR.with(|e| *e.borrow_mut() = CString::new(text).ok());
}

/// Reads a caller's C string, or records an error and returns `None`.
///
/// # Safety
/// `ptr` must be null or point to a NUL-terminated string that stays valid for the call.
unsafe fn path_arg(ptr: *const c_char, what: &str) -> Option<String> {
    if ptr.is_null() {
        set_error(format!("{what} is null"));
        return None;
    }
    match CStr::from_ptr(ptr).to_str() {
        Ok(s) => Some(s.to_owned()),
        Err(_) => {
            set_error(format!("{what} is not valid UTF-8"));
            None
        }
    }
}

/// The library version, e.g. `0.1.2`. The string is static: do not free it.
#[no_mangle]
pub extern "C" fn tk_version() -> *const c_char {
    concat!(env!("CARGO_PKG_VERSION"), "\0").as_ptr() as *const c_char
}

/// The message of the last failed call on this thread, or null when there is none.
/// The pointer stays valid until the next call on this thread that fails.
#[no_mangle]
pub extern "C" fn tk_last_error() -> *const c_char {
    LAST_ERROR.with(|e| match e.borrow().as_ref() {
        Some(s) => s.as_ptr(),
        None => std::ptr::null(),
    })
}

/// Frees a string returned by this library. Null is accepted and ignored.
///
/// # Safety
/// `s` must be null or a pointer returned by [`tk_probe_json`] and not freed yet.
#[no_mangle]
pub unsafe extern "C" fn tk_free_string(s: *mut c_char) {
    if !s.is_null() {
        drop(CString::from_raw(s));
    }
}

/// Lists the tracks of the file at `path` as JSON, or returns null on error.
///
/// The document has a `format` string and a `streams` array; each stream has
/// `index`, `codec`, `type` (`video`, `audio` or `other`), and for video `width` and
/// `height`, for audio `channels` and `sample_rate`. Free the result with
/// [`tk_free_string`].
///
/// # Safety
/// `path` must be a NUL-terminated UTF-8 string.
#[no_mangle]
pub unsafe extern "C" fn tk_probe_json(path: *const c_char) -> *mut c_char {
    let result = catch_unwind(AssertUnwindSafe(|| -> Option<String> {
        let path = path_arg(path, "path")?;
        match probe_json(Path::new(&path)) {
            Ok(json) => Some(json),
            Err(e) => {
                set_error(e);
                None
            }
        }
    }));
    match result {
        Ok(Some(json)) => CString::new(json).map_or(std::ptr::null_mut(), CString::into_raw),
        Ok(None) => std::ptr::null_mut(),
        Err(_) => {
            set_error("internal error (panic) while probing");
            std::ptr::null_mut()
        }
    }
}

/// Writes a copy of `input` to `output` with the index moved to the front.
/// Returns 0 on success and -1 on error.
///
/// # Safety
/// `input` and `output` must be NUL-terminated UTF-8 strings.
#[no_mangle]
pub unsafe extern "C" fn tk_faststart(input: *const c_char, output: *const c_char) -> c_int {
    let result = catch_unwind(AssertUnwindSafe(|| -> Result<(), String> {
        let input = path_arg(input, "input").ok_or("input is missing")?;
        let output = path_arg(output, "output").ok_or("output is missing")?;
        let mut src = File::open(&input).map_err(|e| format!("open {input}: {e}"))?;
        let dst = File::create(&output).map_err(|e| format!("create {output}: {e}"))?;
        let mut dst = BufWriter::new(dst);
        tpt_kinetix_mux::faststart(&mut src, &mut dst).map_err(|e| e.to_string())?;
        dst.flush().map_err(|e| e.to_string())?;
        Ok(())
    }));
    match result {
        Ok(Ok(())) => 0,
        Ok(Err(e)) => {
            set_error(e);
            -1
        }
        Err(_) => {
            set_error("internal error (panic) during faststart");
            -1
        }
    }
}

/// The tracks of `path` as JSON.
fn probe_json(path: &Path) -> Result<String, String> {
    let mut head = [0u8; 4];
    {
        let mut f = File::open(path).map_err(|e| format!("open {}: {e}", path.display()))?;
        let n = f.read(&mut head).map_err(|e| e.to_string())?;
        if n < 4 {
            return Err("file is too short to be a media file".into());
        }
    }
    let (format, streams) = if head == [0x1A, 0x45, 0xDF, 0xA3] {
        let file = File::open(path).map_err(|e| e.to_string())?;
        let reader = MkvReader::open(file).map_err(|e| e.to_string())?;
        ("matroska,webm", reader.streams().to_vec())
    } else if &head == b"DKIF" {
        let data = std::fs::read(path).map_err(|e| e.to_string())?;
        let demuxer = IvfDemuxer::new(data).map_err(|e| e.to_string())?;
        ("ivf", vec![demuxer.stream_info().clone()])
    } else {
        let file = File::open(path).map_err(|e| e.to_string())?;
        let reader = Mp4Reader::open(file).map_err(|e| e.to_string())?;
        ("mov,mp4,m4a,3gp,3g2,mj2", reader.streams())
    };
    Ok(document(format, &streams))
}

fn document(format: &str, streams: &[StreamInfo]) -> String {
    let items: Vec<String> = streams
        .iter()
        .enumerate()
        .map(|(i, s)| stream_json(i, s))
        .collect();
    format!("{{\"format\":\"{}\",\"streams\":[{}]}}", format, items.join(","))
}

fn stream_json(index: usize, s: &StreamInfo) -> String {
    let kind = match s.media_type {
        MediaType::Video => "video",
        MediaType::Audio => "audio",
        _ => "other",
    };
    let mut out = format!(
        "{{\"index\":{index},\"codec\":\"{}\",\"type\":\"{kind}\"",
        s.codec.name()
    );
    match s.media_type {
        MediaType::Video => {
            out.push_str(&format!(",\"width\":{},\"height\":{}", s.width, s.height));
        }
        MediaType::Audio => {
            out.push_str(&format!(
                ",\"channels\":{},\"sample_rate\":{}",
                s.channels, s.sample_rate
            ));
        }
        _ => {}
    }
    out.push('}');
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use tpt_kinetix_core::codec::CodecId;

    #[test]
    fn stream_json_has_the_fields_per_kind() {
        let mut v = StreamInfo::new(0, CodecId::Vp9, 90_000);
        v.media_type = MediaType::Video;
        v.width = 320;
        v.height = 240;
        assert_eq!(
            stream_json(0, &v),
            r#"{"index":0,"codec":"vp9","type":"video","width":320,"height":240}"#
        );
        let mut a = StreamInfo::new(1, CodecId::Opus, 48_000);
        a.media_type = MediaType::Audio;
        a.channels = 2;
        a.sample_rate = 48_000;
        assert_eq!(
            stream_json(1, &a),
            r#"{"index":1,"codec":"opus","type":"audio","channels":2,"sample_rate":48000}"#
        );
    }

    #[test]
    fn null_and_missing_paths_fail_cleanly() {
        unsafe {
            assert!(tk_probe_json(std::ptr::null()).is_null());
            let msg = CStr::from_ptr(tk_last_error()).to_str().unwrap();
            assert!(msg.contains("null"));
            let missing = CString::new("/definitely/not/here.mp4").unwrap();
            assert!(tk_probe_json(missing.as_ptr()).is_null());
            let output = CString::new("/definitely/not/out.mp4").unwrap();
            assert_eq!(tk_faststart(missing.as_ptr(), output.as_ptr()), -1);
        }
    }

    #[test]
    fn version_is_a_static_c_string() {
        let v = unsafe { CStr::from_ptr(tk_version()) }.to_str().unwrap();
        assert_eq!(v, env!("CARGO_PKG_VERSION"));
    }
}
